package com.bank.trading.service;

import com.bank.trading.model.Interval;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Intersection of two sorted non-overlapping interval lists via two pointers.
public class TradingWindowService {
    private static final Logger log = Logger.getLogger(TradingWindowService.class.getName());

    public List<Interval> intersect(List<Interval> eligibility, List<Interval> market) {
        List<Interval> result = new ArrayList<>();
        if (eligibility == null || market == null
                || eligibility.isEmpty() || market.isEmpty()) {
            return result;
        }
        int i = 0, j = 0;
        while (i < eligibility.size() && j < market.size()) {
            Interval a = eligibility.get(i);
            Interval b = market.get(j);
            int lo = Math.max(a.getStart(), b.getStart());
            int hi = Math.min(a.getEnd(), b.getEnd());
            if (lo <= hi) {
                Interval overlap = new Interval(lo, hi);
                result.add(overlap);
                log.fine(() -> "Overlap of " + a + " and " + b + " = " + overlap);
            }
            // Advance whichever interval ends first (it is exhausted).
            if (a.getEnd() < b.getEnd()) {
                i++;
            } else {
                j++;
            }
        }
        log.info(() -> "Tradeable (intersection) windows = " + result);
        return result;
    }
}
