package com.bank.trading;

import com.bank.trading.model.Account;
import com.bank.trading.model.Interval;
import com.bank.trading.service.TradingWindowService;

import java.math.BigDecimal;
import java.util.Date;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class IntervalIntersectionDemo {
    private static final Logger log = Logger.getLogger(IntervalIntersectionDemo.class.getName());

    public static void main(String[] args) {
        setupLogging();
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));

        TradingWindowService service = new TradingWindowService();

        List<Interval> rajeshEligibility = List.of(
                new Interval(0, 2), new Interval(5, 10),
                new Interval(13, 23), new Interval(24, 25));
        List<Interval> market = List.of(
                new Interval(1, 5), new Interval(8, 12),
                new Interval(15, 24), new Interval(25, 26));
        log.info(() -> rajesh.getHolderName() + " (" + rajesh.getAccountId()
                + ") eligibility = " + rajeshEligibility);
        log.info(() -> "Market windows = " + market);
        List<Interval> r1 = service.intersect(rajeshEligibility, market);
        log.info(() -> rajesh.getHolderName() + " tradeable windows = " + r1);

        List<Interval> priyaEligibility = List.of(new Interval(1, 3), new Interval(5, 8));
        List<Interval> market2 = List.of(new Interval(2, 6));
        log.info(() -> priya.getHolderName() + " (" + priya.getAccountId()
                + ") eligibility = " + priyaEligibility + ", market = " + market2);
        List<Interval> r2 = service.intersect(priyaEligibility, market2);
        log.info(() -> priya.getHolderName() + " tradeable windows = " + r2);
    }

    private static void setupLogging() {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.FINE);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.FINE);
    }

    static class BankLogFormatter extends Formatter {
        @Override
        public String format(LogRecord r) {
            return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                    new Date(r.getMillis()), r.getLevel(), r.getMessage());
        }
    }
}
